            gsMatrix<T> G22_inv = ( geoMapDeriv1.row(0).cwiseProduct(geoMapDeriv1.row(0)) +
                                    geoMapDeriv1.row(2).cwiseProduct(geoMapDeriv1.row(2)) +
                                    geoMapDeriv1.row(4).cwiseProduct(geoMapDeriv1.row(4)));


