            gsMatrix<T> DuG11_inv = 2 * (geoMapDeriv2.row(2) + geoMapDeriv2.row(5) + geoMapDeriv2.row(8));

            gsMatrix<T> DuG12_inv = - ( geoMapDeriv2.row(0).cwiseProduct(geoMapDeriv1.row(1)) +
