 {
     GISMO_ASSERT((mat.cols()*mat.rows() == cp.rows()), "Wrong matrix dimension.");
     int counter = 0;
     for(int j = 0; j < mat.rows(); j++){
         for(int i = 0; i < mat.cols(); i++){
             cp(counter, direction) = mat(j,i);
             counter ++;
         }
     }
