                  << m_repKnots.size() << ")." );

    iterator it = begin() + knotIndex;
    iterator L  = std::find_if(it,end(),GS_BIND1ST(std::not_equal_to<T>(),*it));
    reverse_iterator F = std::find_if(reverse_iterator(it),rend(),
                                      GS_BIND1ST(std::not_equal_to<T>(),*it));
