 */
template<typename T>
class benchmark_c_array_memcopy
{
private:
  memory_safeguard<benchmark_c_array_memcopy> _msg;
  index_t n;
  T *m_x, *m_y;

public:
  benchmark_c_array_memcopy(index_t n)
    : _msg(n), n(n), m_x(new T[n]), m_y(new T[n])
  {
#pragma omp parallel for simd
    for (index_t i=0; i<n; ++i)
