  index_t n;
  T *m_x, *m_y, *m_z;

public:
  benchmark_c_array_axpy(index_t n)
    : _msg(n), n(n), m_x(new T[n]), m_y(new T[n]), m_z(new T[n])
  {
#pragma omp parallel for simd
    for (index_t i=0; i<n; ++i)
      m_x[i] = (T)1.0;

#pragma omp parallel for simd
    for (index_t i=0; i<n; ++i)
      m_y[i] = (T)1.0;
  }

  ~benchmark_c_array_axpy()
  {
    delete[] m_x;
    delete[] m_y;
    delete[] m_z;
  }

  index_t operator()()
  {
#pragma omp parallel for simd
    for (index_t i=0; i<n; ++i)
