                s_tilde.col(i1) = t_tilde.reshape(n2*n3,1);
            }
            s_tilde = Us[0] * s_tilde.transpose();
            // step 4: reshape
            r_tilde.col(i) = s_tilde.reshape(n1*n2*n3,1);
        }
        //... result
        r_tilde.reshape(3*n1*n2*n3, 1);
