-	if (!c1)
-	{
-		do
-		{
-			tau *= 0.8;
-
-			pde.w = u_ + tau * s_;
-			A.initialize(pde, basis, opt);
-			A.assemble();
-
-			Kh = A.matrix();
-			fh = A.rhs();
-			rh_new = Kh * (u_ + tau * s_) - fh;
-			Jh_new = A.energy();
-			
-			bool c1 = Jh_new <= Jh + tau * mu*(rh.transpose()*s_).value();
-			iter++;
-		} while (!c1 && iter < maxiter);
-	}
-	else if (c1 && !c2)
-	{
-		do
-		{
-			tau *= 1.2;
-
-			pde.w = u_ + tau * s_;
-			A.initialize(pde, basis, opt);
-			A.assemble();
-
-			Kh = A.matrix();
-			fh = A.rhs();
-			rh_new = Kh * (u_ + tau * s_) - fh;
-			Jh_new = A.energy();
-
