-			bool c2 = (rh_new.transpose()*s_).value() >= sigma*(rh.transpose()*s_).value();
-			iter++;
-		} while (c1 && !c2 && iter < maxiter);
-	}
-	rh = rh_new;
-	Jh = Jh_new;
