+		bcInfo, mapper, 0);
+
+	gsSparseSystem<> sys(mapper);
+	sys.reserve(MA.multiBasis(0), MA.options(), MA.pde().numRhs()); // reserving enough space is crutial for performance!
+	MA.setSparseSystem(sys);
+
