+            //GISMO_ASSERT ( bases.size() == 1, "Only one basis is expected, got"<<bases.size() );
+            gsLinearOperator<>::Ptr op =
+                macroGsInit(
+                    mat,
+                    dims,
+                    innerSize,
+                    overlapSize
+                );
+             result->addOperator(transfer, op );
+        }
+    }
+
+    return result;
+}

