        swapTensorDirection(0, dir, sz, this->m_basis.weights());
        this->m_coefs.resize( sz[0], n * sz.template tail<d-1>().prod() );
        this->m_basis.weights().resize( sz[0], sz.template tail<d-1>().prod() );

