    /// \brief Dereferences the knot-iterator
    reference operator*  () const 
    {
#       if defined(_GLIBCXX_DEBUG) || _SECURE_SCL != 0 
        GISMO_ENSURE(m_upos >= 0 && m_pos + 1< m_dbg, 
